"""This module provides functionality to determine the collected log
files from screl log collection and to provide all paths to the caller
"""
import os
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class GnbScrelLogfileProvider:
    """Logfile provider for snapshot log files"""

    def get_screl_log_file(self, log_directory, collector_config):
        """Determines all screl log files and returns them in a list

        :param str log_directory: The Directory for the log files
        :param dict collector_config: The matching collector config for the screl logs
        """
        screl_files = []

        if collector_config['type'] == 'group':
            logger.warning("Cloud gnb not yet supported by screl logger, no screl log files provied !")

        elif collector_config['type'] == 'screl_sbts':
            zip_files = [os.path.join(log_directory, x) for x in os.listdir(log_directory)
                         if x.lower().endswith('.zip')]
            screl_files += zip_files

        return screl_files
